struct Fibonacci { a: u64, b: u64 }

impl Iterator for Fibonacci {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        let value = self.a;
        self.a = self.b;
        self.b = value + self.b;
        Some(value)
    }
}

let fib = Fibonacci { a: 0, b: 1 };
let total: u64 = fib.take(10).sum();
println!("{total}");

